    "fatehpur-sikri": { n:"फतेहपुर सीकरी", d:"अकबर का भूत-शहर — लाल बलुआ पत्थर का पूरा मुगल राजधानी।", h:"सम्राट अकबर ने चित्तौड़ के विजय के बाद 1571 में फतेहपुर सीकरी की स्थापना अपनी साम्राज्यीय राजधानी के रूप में की। बीस वर्षों के अंदर शहर को छोड़ दिया गया, संभवतः पानी की कमी के कारण।", f:["बुलंद दरवाज़ा — 54 मी. ऊँचा प्रवेश-द्वार","पंच महल, पाँच-मंजिला महल","इबदत ख़ाना, धार्मिक चर्चा का हॉल"], i:"एक दुर्लभ, अद्भुत रूप से पूर्ण मुगल-योजनाबद्ध राजधानी और यूनेस्को विश्व-विरासत स्थल।" },
    "jaisalmer": { n:"जैसलमेर", d:"स्वर्ण-शहर — थार मरुभूमि से उठता किला-शहर।", h:"जैसलमेर की स्थापना 1156 में रावल जैसल ने की, और उसका किला-शहर कभी जीता नहीं गया। पूरा पुराना शहर स्वर्ण-बलुआ पत्थर में निर्मित, जिससे शहर को उसकी उपनाम मिली।", f:["जीता हुआ किला जिसमें 900+ हवेलियाँ","नारागढ़ और पाटवोन-की-हवेली","दृश्य पर सरोवर झील"], i:"एक यूनेस्को-सूचीबद्ध मध्यकालीन मरुभूमि-शहर और राजपूताना का रत्न।" },
