    "sasan": { n:"ससाम मिरर गार्डन", d:"मण्डवी नदी-किनारे दर्पण-पवेलियन और झरने — गोवा का सबसे फोटो-योग्य बगीचा।", h:"ससाम मिरर गार्डन 2011 में पनाजी में मण्डवी नदी-किनारे खुला। उसके ग्लास-पवेलियन, झरने और प्रसिद्ध मरमेड मूर्ति ने इसे यात्रियों और गोवानी दोनों का पसंदीदा बना दिया।", f:["दर्पण-पवेलियन और झरने","प्रतीकात्मक मरमेड मूर्ति","मण्डवी नदी-किनारे स्थिति"], i:"गोवा की सार्वजनिक बगीचा-संस्कृति का एक आधुनिक प्रमुख बिंदु।" },
    "shivaji-park": { n:"शिवाजी पार्क", d:"सदी पुराना शहरी पार्क, जू और वनस्पति-उद्यान, दादर के हृदय में।", h:"शिवाजी पार्क की स्थापना 1918 में हुई और यह मुंबई के सबसे पुराने और सबसे बड़े पार्कों में से एक है। इसके प्रवेश द्वार का निशान ऐतिहासिक डेविड सस्सून घड़ी-गगनचुंबी है, और उसके घास-मैदानों में एक जू, वनस्पति-उद्यान और खुले मैदान हैं जहाँ परिवार शाम-सैर के लिए जमा होते हैं। 2021 में पार्क को जीजामाता उद्यान नाम दिया गया।", f:["1918 उद्भव और डेविड सस्सून घड़ी-गगनचुंबी","नगर-पालिका जू और वनस्पति-उद्यान","शाम-सैर के लिए घास-मैदान"], i:"दादर का हरा हृदय, सदी से अधिक समय से मुंबई का प्यारा।" }
